INSERT INTO item VALUES (1398,'Feather Token, Swan Boat','Wondrous',NULL,'No','Moderate conjuration','12','450 gp',NULL,'Craft Wondrous Item, major creation',NULL,NULL,'\n      <div topic=\"Feather Token\" level=\"8\"><p><b>Feather Token:</b> Each of these items is a small feather that has a power to suit a special need. The kinds of tokens are described below. Each token is usable once.</p><p><i>Anchor:</i> A token useful to moor a craft in water so as to render it immobile for up to one day.</p><p><i>Bird:</i> A token that can be used to deliver a small written message unerringly to a designated target as would a carrier pigeon. The token lasts as long as it takes to carry the message.</p><p><i>Fan:</i> A token that forms a huge flapping fan, causing a breeze of sufficient strength to propel one ship (about 25 mph). This wind is not cumulative with existing wind speed. The token can, however, be used to lessen existing winds, creating an area of relative calm or lighter winds (but wave size in a storm is not affected). The fan can be used for up to 8 hours. It does not function on land.</p><p><i>Swan Boat:</i> A token that forms a swanlike boat capable of moving on water at a speed of 60 feet. It can carry eight horses and gear or thirty-two Medium characters or any equivalent combination. The boat lasts for one day.</p><p><i>Tree:</i> A token that causes a great oak to spring into being (5-foot diameter trunk, 60-foot height, 40-foot top diameter). This is an instantaneous effect.</p><p><i>Whip:</i> A token that forms into a huge leather whip and wields itself against any opponent desired just like a dancing weapon. The weapon has a +10 base attack bonus, does 1d6+1 points of damage, has a +1 enhancement bonus on attack and damage rolls, and a makes a free grapple attack (with a +15 attack bonus) if it hits. The whip lasts no longer than 1 hour.</p><p>Moderate conjuration; CL 12th; Craft Wondrous Item, <i>major creation</i>; Price 50 gp (<i>anchor</i>), 300 gp (<i>bird</i>), 200 gp (<i>fan</i>), 450 gp (<i>swan boat</i>), 400 gp (<i>tree</i>), 500 gp (<i>whip</i>).</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1399,'Feather Token, Tree','Wondrous',NULL,'No','Moderate conjuration','12','400 gp',NULL,'Craft Wondrous Item, major creation',NULL,NULL,'\n      <div topic=\"Feather Token\" level=\"8\"><p><b>Feather Token:</b> Each of these items is a small feather that has a power to suit a special need. The kinds of tokens are described below. Each token is usable once.</p><p><i>Anchor:</i> A token useful to moor a craft in water so as to render it immobile for up to one day.</p><p><i>Bird:</i> A token that can be used to deliver a small written message unerringly to a designated target as would a carrier pigeon. The token lasts as long as it takes to carry the message.</p><p><i>Fan:</i> A token that forms a huge flapping fan, causing a breeze of sufficient strength to propel one ship (about 25 mph). This wind is not cumulative with existing wind speed. The token can, however, be used to lessen existing winds, creating an area of relative calm or lighter winds (but wave size in a storm is not affected). The fan can be used for up to 8 hours. It does not function on land.</p><p><i>Swan Boat:</i> A token that forms a swanlike boat capable of moving on water at a speed of 60 feet. It can carry eight horses and gear or thirty-two Medium characters or any equivalent combination. The boat lasts for one day.</p><p><i>Tree:</i> A token that causes a great oak to spring into being (5-foot diameter trunk, 60-foot height, 40-foot top diameter). This is an instantaneous effect.</p><p><i>Whip:</i> A token that forms into a huge leather whip and wields itself against any opponent desired just like a dancing weapon. The weapon has a +10 base attack bonus, does 1d6+1 points of damage, has a +1 enhancement bonus on attack and damage rolls, and a makes a free grapple attack (with a +15 attack bonus) if it hits. The whip lasts no longer than 1 hour.</p><p>Moderate conjuration; CL 12th; Craft Wondrous Item, <i>major creation</i>; Price 50 gp (<i>anchor</i>), 300 gp (<i>bird</i>), 200 gp (<i>fan</i>), 450 gp (<i>swan boat</i>), 400 gp (<i>tree</i>), 500 gp (<i>whip</i>).</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1400,'Feather Token, Whip','Wondrous',NULL,'No','Moderate conjuration','12','500 gp',NULL,'Craft Wondrous Item, major creation',NULL,NULL,'\n      <div topic=\"Feather Token\" level=\"8\"><p><b>Feather Token:</b> Each of these items is a small feather that has a power to suit a special need. The kinds of tokens are described below. Each token is usable once.</p><p><i>Anchor:</i> A token useful to moor a craft in water so as to render it immobile for up to one day.</p><p><i>Bird:</i> A token that can be used to deliver a small written message unerringly to a designated target as would a carrier pigeon. The token lasts as long as it takes to carry the message.</p><p><i>Fan:</i> A token that forms a huge flapping fan, causing a breeze of sufficient strength to propel one ship (about 25 mph). This wind is not cumulative with existing wind speed. The token can, however, be used to lessen existing winds, creating an area of relative calm or lighter winds (but wave size in a storm is not affected). The fan can be used for up to 8 hours. It does not function on land.</p><p><i>Swan Boat:</i> A token that forms a swanlike boat capable of moving on water at a speed of 60 feet. It can carry eight horses and gear or thirty-two Medium characters or any equivalent combination. The boat lasts for one day.</p><p><i>Tree:</i> A token that causes a great oak to spring into being (5-foot diameter trunk, 60-foot height, 40-foot top diameter). This is an instantaneous effect.</p><p><i>Whip:</i> A token that forms into a huge leather whip and wields itself against any opponent desired just like a dancing weapon. The weapon has a +10 base attack bonus, does 1d6+1 points of damage, has a +1 enhancement bonus on attack and damage rolls, and a makes a free grapple attack (with a +15 attack bonus) if it hits. The whip lasts no longer than 1 hour.</p><p>Moderate conjuration; CL 12th; Craft Wondrous Item, <i>major creation</i>; Price 50 gp (<i>anchor</i>), 300 gp (<i>bird</i>), 200 gp (<i>fan</i>), 450 gp (<i>swan boat</i>), 400 gp (<i>tree</i>), 500 gp (<i>whip</i>).</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1401,'Gauntlets of Ogre Power','Wondrous',NULL,'No','Faint transmutation','6','4,000 gp',NULL,'Craft Wondrous Item, bull\'s strength',NULL,'4 lb','\n      <div topic=\"Gauntlets of Ogre Power\" level=\"8\"><p><b>Gauntlets of Ogre Power:</b> These gauntlets are made of tough leather with iron studs running across the back of the hands and fingers. They grant the wearer great strength, adding a +2 enhancement bonus to his Strength score. Both gauntlets must be worn for the magic to be effective.</p><p>Faint transmutation; CL 6th; Craft Wondrous Item, <i>bull\'s strength</i>; Price 4,000 gp; Weight 4 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1402,'Gauntlet of Rust','Wondrous',NULL,'No','Moderate transmutation','7','11,500 gp',NULL,'Craft Wondrous Item, rusting grasp',NULL,'2 lb','\n      <div topic=\"Gauntlet of Rust\" level=\"8\"><p><b>Gauntlet of Rust:</b> This single metal gauntlet looks rusted and pitted but is actually quite powerful. Once per day, it can affect an object as with the <i>rusting grasp</i> spell. It also completely protects the wearer and her gear from rust (magical or otherwise), including the attack of a rust monster.</p><p>Moderate transmutation; CL 7th; Craft Wondrous Item, <i>rusting grasp</i>; Price 11,500 gp; Weight 2 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1403,'Gem of Brightness','Wondrous',NULL,'No','Faint evocation','6','13,000 gp',NULL,'Craft Wondrous Item, daylight',NULL,NULL,'\n      <div topic=\"Gem of Brightness\" level=\"8\"><p><b>Gem of Brightness:</b> This crystal appears to be a long, rough prism. Upon utterance of a command word, the crystal emits bright light of one of three sorts.</p><ul>\n <li> One command word causes the gem to shed light as a hooded lantern. This use of the gem does not expend any charges.</li>\n <li> Another command word causes the <i>gem of brightness</i> to send out a bright ray 1 foot in diameter and 50 feet long. This strikes as a ranged touch attack, and any creature struck by this beam is blinded for 1d4 rounds unless it makes a DC 14 Fortitude save. This use of the gem expends 1 charge.</li>\n <li> The third command word causes the gem to flare in a blinding flash of light that fills a 30-foot cone. Although this glare lasts but a moment, any creature within the cone must make a DC 14 Fortitude save or be blinded for 1d4 rounds. This use expends 5 charges.</li>\n</ul><p>A newly created <i>gem of brightness</i> has 50 charges. When all its charges are expended, the gem becomes nonmagical.</p><p>Faint evocation; CL 6th; Craft Wondrous Item, <i>daylight</i>; Price 13,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1404,'Gem of Seeing','Wondrous',NULL,'No','Moderate divination','10','75,000 gp',NULL,'Craft Wondrous Item, true seeing',NULL,NULL,'\n      <div topic=\"Gem of Seeing\" level=\"8\"><p><b>Gem of Seeing:</b> This finely cut and polished stone is indistinguishable from an ordinary jewel in appearance. When it is gazed through, a <i>gem of seeing</i> enables the user to see as though she were affected by the <i>true seeing</i> spell. A <i>gem of seeing</i> can be used for as much as 30 minutes a day, divided up into periods of minutes or rounds as the user sees fit.</p><p>Moderate divination; CL 10th; Craft Wondrous Item, <i>true seeing</i>; Price 75,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1405,'Gloves of Arrow Snaring','Wondrous',NULL,'No','Faint abjuration','3','4,000 gp',NULL,'Craft Wondrous Item, shield',NULL,NULL,'\n      <div topic=\"Gloves of Arrow Snaring\" level=\"8\"><p><b>Gloves of Arrow Snaring:</b> Once snugly worn, these gloves seem to meld with the hands, becoming almost invisible. Twice per day, the wearer can act as if he had the Snatch Arrows feat, even if he does not meet the prerequisites for it. Both gloves must be worn for the magic to be effective. At least one hand must be free to take advantage of the magic.</p><p>Faint abjuration; CL 3rd; Craft Wondrous Item, <i>shield</i>; Price 4,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1406,'Gloves of Dexterity +2','Wondrous',NULL,'No','Moderate transmutation','8','4,000 gp',NULL,'Craft Wondrous Item, cat\'s grace',NULL,NULL,'\n      <div topic=\"Gloves of Dexterity\" level=\"8\"><p><b>Gloves of Dexterity:</b> These thin leather gloves are very flexible and allow for delicate manipulation. They add to the wearer\'s Dexterity score in the form of an enhancement bonus of +2, +4, or +6. Both gloves must be worn for the magic to be effective.</p><p>Moderate transmutation; CL 8th; Craft Wondrous Item, <i>cat\'s grace</i>; Price 4,000 gp (+2), 16,000 gp (+4), 36,000 gp (+6).</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1407,'Gloves of Dexterity +4','Wondrous',NULL,'No','Moderate transmutation','8','16,000 gp',NULL,'Craft Wondrous Item, cat\'s grace',NULL,NULL,'\n      <div topic=\"Gloves of Dexterity\" level=\"8\"><p><b>Gloves of Dexterity:</b> These thin leather gloves are very flexible and allow for delicate manipulation. They add to the wearer\'s Dexterity score in the form of an enhancement bonus of +2, +4, or +6. Both gloves must be worn for the magic to be effective.</p><p>Moderate transmutation; CL 8th; Craft Wondrous Item, <i>cat\'s grace</i>; Price 4,000 gp (+2), 16,000 gp (+4), 36,000 gp (+6).</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1408,'Gloves of Dexterity +6','Wondrous',NULL,'No','Moderate transmutation','8','36,000 gp',NULL,'Craft Wondrous Item, cat\'s grace',NULL,NULL,'\n      <div topic=\"Gloves of Dexterity\" level=\"8\"><p><b>Gloves of Dexterity:</b> These thin leather gloves are very flexible and allow for delicate manipulation. They add to the wearer\'s Dexterity score in the form of an enhancement bonus of +2, +4, or +6. Both gloves must be worn for the magic to be effective.</p><p>Moderate transmutation; CL 8th; Craft Wondrous Item, <i>cat\'s grace</i>; Price 4,000 gp (+2), 16,000 gp (+4), 36,000 gp (+6).</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1409,'Glove of Storing','Wondrous',NULL,'No','Faint transmutation','6','10,000 gp (one glove)',NULL,'Craft Wondrous Item, shrink item',NULL,NULL,'\n      <div topic=\"Glove of Storing\" level=\"8\"><p><b>Glove of Storing:</b> This device is a simple leather glove. On command, one item held in the hand wearing the glove disappears. The item can weigh no more than 20 pounds and must be able to be held in one hand. While stored, the item has negligible weight. With a snap of the fingers wearing the glove, the item reappears. A glove can only store one item at a time. Storing or retrieving the item is a free action. The item is held in stasis and shrunk down so small within the palm of the glove that it cannot be seen. Spell durations are not suppressed, but continue to expire. If an effect is suppressed or dispelled, the stored item appears instantly.</p><p>Faint transmutation; CL 6th; Craft Wondrous Item, <i>shrink item</i>; Price 10,000 gp (one glove).</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1410,'Gloves of Swimming and Climbing','Wondrous',NULL,'No','Faint transmutation','5','6,250 gp',NULL,'Craft Wondrous Item, bull\'s strength, cat\'s grace',NULL,NULL,'\n      <div topic=\"Gloves of Swimming and Climbing\" level=\"8\"><p><b>Gloves of Swimming and Climbing:</b> These apparently normal lightweight gloves grant a +5 competence bonus on Swim checks and Climb checks. Both gloves must be worn for the magic to be effective.</p><p>Faint transmutation; CL 5th; Craft Wondrous Item, <i>bull\'s strength</i>,  <i>cat\'s grace</i>; Price 6,250 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1411,'Goggles of Minute Seeing','Wondrous',NULL,'No','Faint divination','3','1,250 gp',NULL,'Craft Wondrous Item, true seeing',NULL,NULL,'\n      <div topic=\"Goggles of Minute Seeing\" level=\"8\"><p><b>Goggles of Minute Seeing:</b> The lenses of this item are made of special crystal. When placed over the eyes of the wearer, the lenses enable her to see much better than normal at distances of 1 foot or less, granting her a +5 competence bonus on Search checks to find secret doors, traps, and similar concealed objects. Both lenses must be worn for the magic to be effective.</p><p>Faint divination; CL 3rd; Craft Wondrous Item, <i>true seeing</i>; Price 1,250 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1412,'Goggles of Night','Wondrous',NULL,'No','Faint transmutation','3','12,000 gp',NULL,'Craft Wondrous Item, darkvision',NULL,NULL,'\n      <div topic=\"Goggles of Night\" level=\"8\"><p><b>Goggles of Night:</b> The lenses of this item are made of dark crystal. Even though the lenses are opaque, when placed over the eyes of the wearer they enable him to see normally and also grant him 60-foot darkvision. Both lenses must be worn for the magic to be effective.</p><p>Faint transmutation; CL 3rd; Craft Wondrous Item, <i>darkvision</i>; Price 12,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1413,'Golem Manual','Wondrous',NULL,'No','Strong abjuration and enchantment','16','44,000 gp',NULL,'Craft Construct, creator must be caster level 16th, antimagic field, geas/quest, symbol of stunning','2,900 gp + 7,872 XP','5 lb','\n      <div topic=\"Golem Manual\" level=\"8\"><p><b>Golem Manual:</b> A <i>golem manual</i> contains information, incantations and magical power that help a character to craft a golem. The instructions therein grant a +5 competence bonus on skill checks made to craft the golem\'s body. Each manual also holds the prerequisite spells needed for a specific golem, effectively grants the builder use of the Craft Construct feat during the construction of the golem, and grants the character an increase to her caster level for the purpose of crafting a golem. Any golem built using a <i>golem manual</i> does not cost the creator any XP, since the requisite XP are \'contained\' in the book and \'expended\' by the book during the creation process.</p><p>The spells included in a <i>golem manual</i> require a spell trigger activation and can be activated only to assist in the construction of a golem. The cost of the book does not include the cost of constructing the golem\'s body. Once the golem is finished, the writing in the manual fades and the book is consumed in flames. When the book\'s ashes are sprinkled upon the golem, it becomes fully animated.</p><p><i>Clay Golem Manual:</i> The book contains <i>animate objects</i>,  <i>bless</i>,  <i>commune</i>,  <i>prayer</i>, and <i>resurrection</i>. The reader may treat her caster level as two levels higher than normal for the purpose of crafting a clay golem. The book supplies 1,540 XP for the creation of a clay golem.</p><p>Moderate conjuration, divination, enchantment, and transmutation; CL 11th; Craft Construct, creator must be caster level 11th, <i>animate objects</i>,  <i>commune</i>,  <i>prayer</i>,  <i>resurrection</i>; Price 12,000 gp; Cost 2,150 gp + 1,712 XP; Weight 5 lb.</p><p><i>Flesh Golem Manual:</i> The book contains <i>animate dead</i>,  <i>bull\'s strength</i>,  <i>geas/quest</i>,  and <i>limited wish</i>. The reader may treat her caster level as one level higher than normal for the purpose of crafting a flesh golem. The book supplies 780 XP for the creation of a flesh golem.</p><p>Moderate enchantment, necromancy [evil], and transmutation; CL 8th; Craft Construct, creator must be caster level 8th, <i>animate dead</i>,  <i>bull\'s strength</i>,  <i>geas/quest</i>,  <i>limited wish</i>; Price 8,000 gp; Cost 2,050 gp + 944 XP; Weight 5 lb.</p><p><i>Iron Golem Manual:</i> The book contains <i>cloudkill</i>,  <i>geas/quest</i>,  <i>limited wish</i>, and <i>polymorph any object</i>. The reader may treat her caster level as four levels higher than normal for the purpose of crafting a iron golem. The book supplies 5,600 XP for the creation of a iron golem.</p><p>Strong conjuration, enchantment and transmutation; CL 16th; Craft Construct, creator must be caster level 16th, <i>cloudkill</i>,  <i>geas/quest</i>,  <i>limited wish</i>,  <i>polymorph any object</i>; Price 35,000 gp; Cost 3,500 gp + 5,880 XP; Weight 5 lb.</p><p><i>Stone Golem Manual:</i> The book contains <i>geas/quest</i>,  <i>limited wish</i>,  <i>polymorph any object</i>, and <i>slow</i>. The reader may treat her caster level as three levels higher than normal for the purpose of crafting a stone golem. The book supplies 3,400 XP for the creation of a stone golem.</p><p>Strong abjuration and enchantment; CL 14th; Craft Construct, creator must be caster level 14th, <i>antimagic field</i>,  <i>geas/quest</i>,  <i>symbol of stunning</i>; Price 22,000 gp; Cost 2,500 gp + 3,600 XP; Weight 5 lb.</p><p><i>Stone Golem Manual</i>,  <i>Greater:</i> The book contains <i>geas/quest</i>,  <i>limited wish</i>,  <i>polymorph any object</i>, and <i>slow</i>. The reader may treat her caster level as three levels higher than normal for the purpose of crafting a stone golem. The book supplies 7,640 XP for the creation of a greater stone golem.</p><p>Strong abjuration and enchantment; CL 16th; Craft Construct, creator must be caster level 16th, <i>antimagic field</i>,  <i>geas/quest</i>,  <i>symbol of stunning</i>; Price 44,000 gp; Cost 2,900 gp + 7,872 XP; Weight 5 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1414,'Hand of Glory','Wondrous',NULL,'No','Faint varied','5','8,000 gp',NULL,'Craft Wondrous Item, animate dead, daylight, detect invisibility',NULL,'2 lb','\n      <div topic=\"Hand of Glory\" level=\"8\"><p><b>Hand of Glory:</b> This mummified human hand hangs by a leather cord around a character\'s neck (taking up space as a magic necklace would). If a magic ring is placed on one of the fingers of the hand, the wearer benefits from the ring as if wearing it herself, and it does not count against her two-ring limit. The hand can wear only one ring at a time. Even without a ring, the hand itself allows its wearer to use <i>daylight</i> and <i>see invisibility</i> each once per day.</p><p>Faint varied; CL 5th; Craft Wondrous Item,  <i>animate dead</i>, <i>daylight</i>,  <i>detect invisibility</i>; Price 8,000 gp; Weight 2 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1415,'Hand of the Mage','Wondrous',NULL,'No','Faint transmutation','2','900 gp',NULL,'Craft Wondrous Item, mage hand',NULL,'2 lb','\n      <div topic=\"Hand of the Mage\" level=\"8\"><p><b>Hand of the Mage:</b> This mummified elf hand hangs by a golden chain around a character\'s neck (taking up space as a magic necklace would). It allows the wearer to utilize the spell <i>mage hand</i> at will.</p><p>Faint transmutation; CL 2nd; Craft Wondrous Item, <i>mage hand</i>; Price 900 gp; Weight 2 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1416,'Handy Haversack','Wondrous',NULL,'No','Moderate conjuration','9','2,000 gp',NULL,'Craft Wondrous Item, secret chest',NULL,'5 lb','\n      <div topic=\"Handy Haversack\" level=\"8\"><p><b>Handy Haversack:</b> A backpack of this sort appears to be well made, well used, and quite ordinary. It is constructed of finely tanned leather, and the straps have brass hardware and buckles. It has two side pouches, each of which appears large enough to hold about a quart of material. In fact, each is like a <i>bag of holding</i> and can actually hold material of as much as 2 cubic feet in volume or 20 pounds in weight. The large central portion of the pack can contain up to 8 cubic feet or 80 pounds of material. Even when so filled, the backpack always weighs only 5 pounds.</p><p>While such storage is useful enough, the pack has an even greater power in addition. When the wearer reaches into it for a specific item, that item is always on top. Thus, no digging around and fumbling is ever necessary to find what a haversack contains. Retrieving any specific item from a haversack is a move action, but it does not provoke the attacks of opportunity that retrieving a stored item usually does.</p><p>Moderate conjuration; CL 9th; Craft Wondrous Item, <i>secret chest</i>; Price 2,000 gp; Weight 5 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1417,'Harp of Charming','Wondrous',NULL,'No','Faint enchantment','5','7,500 gp',NULL,'Craft Wondrous Item, suggestion',NULL,'5 lb','\n      <div topic=\"Harp of Charming\" level=\"8\"><p><b>Harp of Charming:</b> This instrument is a golden, intricately carved harp. When played, it enables the performer to work one <i>suggestion</i> (as the spell, Will DC 14 negates) into the music for each 10 minutes of playing if he can succeed on a DC 14 Perform (string instruments) check. If the check fails, the audience cannot be affected by any further performances from the harpist for 24 hours.</p><p>Faint enchantment; CL 5th; Craft Wondrous Item, <i>suggestion</i>; Price 7,500 gp; Weight 5 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1418,'Hat of Disguise','Wondrous',NULL,'No','Faint illusion','1','1,800 gp',NULL,'Craft Wondrous Item, disguise self',NULL,NULL,'\n      <div topic=\"Hat of Disguise\" level=\"8\"><p><b>Hat of Disguise:</b> This apparently normal hat allows its wearer to alter her appearance as with a <i>disguise self</i> spell. As part of the disguise, the hat can be changed to appear as a comb, ribbon, headband, cap, coif, hood, helmet, and so on.</p><p>Faint illusion; CL 1st; Craft Wondrous Item, <i>disguise self</i>; Price 1,800 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1419,'Headband of Intellect +2','Wondrous',NULL,'No','Moderate transmutation','8','4,000 gp',NULL,'Craft Wondrous Item, fox\'s cunning',NULL,NULL,'\n      <div topic=\"Headband of Intellect\" level=\"8\"><p><b>Headband of Intellect:</b> This device is a light cord with a small gem set so that it rests upon the forehead of the wearer. The headband adds to the wearer\'s Intelligence score in the form of an enhancement bonus of +2, +4, or +6. This enhancement bonus does not earn the wearer extra skill points when a new level is attained; use the unenhanced Intelligence bonus to determine skill points.</p><p>Moderate transmutation; CL 8th; Craft Wondrous Item, <i>fox\'s cunning</i>; Price 4,000 gp (+2), 16,000 gp (+4), 36,000 gp (+6).</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1420,'Headband of Intellect +4','Wondrous',NULL,'No','Moderate transmutation','8','16,000 gp',NULL,'Craft Wondrous Item, fox\'s cunning',NULL,NULL,'\n      <div topic=\"Headband of Intellect\" level=\"8\"><p><b>Headband of Intellect:</b> This device is a light cord with a small gem set so that it rests upon the forehead of the wearer. The headband adds to the wearer\'s Intelligence score in the form of an enhancement bonus of +2, +4, or +6. This enhancement bonus does not earn the wearer extra skill points when a new level is attained; use the unenhanced Intelligence bonus to determine skill points.</p><p>Moderate transmutation; CL 8th; Craft Wondrous Item, <i>fox\'s cunning</i>; Price 4,000 gp (+2), 16,000 gp (+4), 36,000 gp (+6).</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1421,'Headband of Intellect +6','Wondrous',NULL,'No','Moderate transmutation','8','36,000 gp',NULL,'Craft Wondrous Item, fox\'s cunning',NULL,NULL,'\n      <div topic=\"Headband of Intellect\" level=\"8\"><p><b>Headband of Intellect:</b> This device is a light cord with a small gem set so that it rests upon the forehead of the wearer. The headband adds to the wearer\'s Intelligence score in the form of an enhancement bonus of +2, +4, or +6. This enhancement bonus does not earn the wearer extra skill points when a new level is attained; use the unenhanced Intelligence bonus to determine skill points.</p><p>Moderate transmutation; CL 8th; Craft Wondrous Item, <i>fox\'s cunning</i>; Price 4,000 gp (+2), 16,000 gp (+4), 36,000 gp (+6).</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1422,'Helm of Brilliance','Wondrous',NULL,'No','Strong varied','13','125,000 gp',NULL,'Craft Wondrous Item, detect undead, fireball, flame blade, light, prismatic spray, protection from energy, wall of fire',NULL,'3 lb','\n      <div topic=\"Helm of Brilliance\" level=\"8\"><p><b>Helm of Brilliance:</b> This normal-looking helm takes its true form and manifests its powers when the user dons it and speaks the command word. Made of brilliant silver and polished steel, a newly created helm is set with large magic gems: ten diamonds, twenty rubies, thirty fire opals, and forty opals. When struck by bright light, the helm scintillates and sends forth reflective rays in all directions from its crownlike, gem-tipped spikes. The jewels\' functions are as follows:</p><ul>\n <li> Diamond: <i>Prismatic spray</i> (save DC 20)</li>\n <li> Ruby: <i>Wall of fire</i></li>\n <li> Fire opal: <i>fireball</i> (10d6, Reflex DC 20 half )</li>\n <li> Opal: <i>Daylight</i></li>\n</ul><p>The helm may be used once per round, but each gem can perform its spell-like power just once. Until all its jewels are depleted, a <i>helm of brilliance</i> also has the following magical properties when activated.</p><ul>\n <li> It emanates a bluish light when undead are within 30 feet. This light causes 1d6 points of damage per round to all such creatures within that range.</li>\n <li> The wearer may command any weapon he wields to become a flaming weapon. This is in addition to whatever abilities the weapon may already have (unless the weapon already is a flaming weapon). The command takes 1 round to take effect.</li>\n <li> The helm provides fire resistance 30. This protection does not stack with similar protection from other sources.</li>\n</ul><p>Once all its jewels have lost their magic, the helm loses its powers and the gems turn to worthless powder. Removing a jewel destroys it.</p><p>If a creature wearing the helm is damaged by magical fire (after the fire protection is taken into account) and fails an additional DC 15 Will save, the remaining gems on the helm overload and detonate. Remaining diamonds become <i>prismatic sprays</i> that each randomly target a creature within range (possibly the wearer), rubies become straight-line <i>walls of fire</i> extending outward in a random direction from the helm wearer, and fire opals become <i>fireballs</i> centered on the helm wearer. The opals and the helm itself are destroyed.</p><p>Strong varied; CL 13th; Craft Wondrous Item, <i>detect undead</i>,  <i>fireball</i>,  <i>flame blade</i>,  <i>light</i>,  <i>prismatic spray</i>,  <i>protection from energy</i>,  <i>wall of fire</i>; Price 125,000 gp; Weight 3 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1423,'Helm of Comprehend Languages and Read Magic','Wondrous',NULL,'No','Faint divination','4','5,200 gp',NULL,'Craft Wondrous Item, comprehend languages, read magic',NULL,'3 lb','\n      <div topic=\"Helm of Comprehend Languages and Read Magic\" level=\"8\"><p><b>Helm of Comprehend Languages and Read Magic:</b> Appearing as a normal helmet, a <i>helm of comprehend languages and read magic</i> grants its wearer the ability to understand the spoken words of any creature and to read text in any language and any magical writing. The wearer gains a +5 competence bonus on Decipher Script checks to understand messages written in incomplete, archaic, or exotic forms. Note that understanding a magical text does not necessarily imply spell use.</p><p>Faint divination; CL 4th; Craft Wondrous Item, <i>comprehend languages</i>,  <i>read magic</i>; Price 5,200 gp; Weight 3 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1424,'Helm of Telepathy','Wondrous',NULL,'No','Faint divination and enchantment','5','27,000 gp',NULL,'Craft Wondrous Item, detect thoughts, suggestion',NULL,'3 lb','\n      <div topic=\"Helm of Telepathy\" level=\"8\"><p><b>Helm of Telepathy:</b> The wearer can use <i>detect thoughts</i> at will. Furthermore, he can send a telepathic message to anyone whose surface thoughts he is reading (allowing two-way communication). Once per day, the wearer of the helm can implant a <i>suggestion</i> (as the spell, Will DC 14 negates) along with his telepathic message.</p><p>Faint divination and enchantment; CL 5th; Craft Wondrous Item, <i>detect thoughts</i>,  <i>suggestion</i>; Price 27,000 gp; Weight 3 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1425,'Helm of Teleportation','Wondrous',NULL,'No','Moderate conjuration','9','73,500 gp',NULL,'Craft Wondrous Item, teleport',NULL,'3 lb','\n      <div topic=\"Helm of Teleportation\" level=\"8\"><p><b>Helm of Teleportation:</b> A character wearing this device may <i>teleport</i> three times per day, exactly as if he had cast the spell of the same name.</p><p>Moderate conjuration; CL 9th; Craft Wondrous Item, <i>teleport</i>; Price 73,500 gp; Weight 3 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1426,'Helm of Underwater Action','Wondrous',NULL,'No','Faint transmutation','5','57,000 gp',NULL,'Craft Wondrous Item, water breathing',NULL,'3 lb','\n      <div topic=\"Helm of Underwater Action\" level=\"8\"><p><b>Helm of Underwater Action:</b> The wearer of this helmet can see underwater. Drawing the small lenses in compartments on either side into position before the wearer\'s eyes activates the visual properties of the helm, allowing her to see five times farther than water and light conditions would allow for normal human vision. (Weeds, obstructions, and the like block vision in the usual manner.) If the command word is spoken, the <i>helm of underwater action</i> creates a globe of air around the wearer\'s head and maintains it until the command word is spoken again, enabling her to breathe freely.</p><p>Faint transmutation; CL 5th; Craft Wondrous Item, <i>water breathing</i>; Price 57,000 gp; Weight 3 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1427,'Horn of Blasting','Wondrous',NULL,'No','Moderate evocation','7','20,000 gp',NULL,'Craft Wondrous Item, shout',NULL,'1 lb','\n      <div topic=\"Horn of Blasting\" level=\"8\"><p><b>Horn of Blasting:</b> This horn appears to be a normal trumpet. It can be sounded as a normal horn, but if the command word is spoken and the instrument is then played, it deals 5d6 points of sonic damage to creatures within a 40-foot cone and causes them to be deafened for 2d6 rounds (a DC 16 Fortitude save reduces the damage by half and negates the deafening). Crystalline objects and creatures take 7d6 points of sonic damage, with no save unless they\'re held, worn, or carried by creatures (Will DC 16 negates).</p><p>If a <i>horn of blasting</i> is used magically more than once in a given day, there is a 20% cumulative chance with each extra use that it explodes and deals 10d6 points of damage to the person sounding it.</p><p>Moderate evocation; CL 7th; Craft Wondrous Item, <i>shout</i>; Price 20,000 gp; Weight 1 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1428,'Horn of Blasting, Greater','Wondrous',NULL,'No','Strong evocation','16','70,000 gp',NULL,'Craft Wondrous Item, greater shout',NULL,'1 lb','\n      <div topic=\"Horn of Blasting, Greater\" level=\"8\"><p><b>Horn of Blasting, Greater:</b> This horn functions as a <i>horn of blasting</i>,  except that it deals 10d6 points of sonic damage, stuns creatures for 1 round, and deafens them for 4d6 rounds (a DC 19 Fortitude reduces the damage by half and negates the stunning and deafening). Crystalline objects take 16d6 points of sonic damage as described for the <i>horn of blasting</i>. A <i>greater horn of blasting</i> also has a 20% cumulative chance of exploding.</p><p>Strong evocation; CL 16th; Craft Wondrous Item, <i>greater shout</i>; Price 70,000 gp; Weight 1 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1429,'Horn of Fog','Wondrous',NULL,'No','Faint conjuration','3','2,000 gp',NULL,'Craft Wondrous Item, obscuring mist',NULL,'1 lb','\n      <div topic=\"Horn of Fog\" level=\"8\"><p><b>Horn of Fog:</b> This small bugle allows its possessor to blow forth a thick cloud of heavy fog similar to that of an <i>obscuring mist</i> spell. The fog covers a 10-foot square next to the horn blower each round that the user continues to blow the horn; fog clouds travel 10 feet each round in a straight line from the emanation point unless blocked by something substantial such as a wall. The device makes a deep, foghorn-like noise, with the note dropping abruptly to a lower register at the end of each blast. The fog dissipates after 3 minutes. A moderate wind (11+ mph) disperses the fog in 4 rounds; a strong wind (21+ mph) disperses the fog in 1 round.</p><p>Faint conjuration; CL 3rd; Craft Wondrous Item, <i>obscuring mist</i>; Price 2,000 gp; Weight 1 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1430,'Horn of Goodness/Evil','Wondrous',NULL,'No','Faint abjuration','6','6,500 gp',NULL,'Craft Wondrous Item, magic circle against good, magic circle against evil',NULL,'1 lb','\n      <div topic=\"Horn of Goodness/Evil\" level=\"8\"><p><b>Horn of Goodness/Evil:</b> This trumpet adapts itself to its owner, so it produces either a good or an evil effect depending on the owner\'s alignment. If the owner is neither good nor evil, the horn has no power whatsoever. If he is good, then blowing the horn has the effect of a <i>magic circle against evil</i>. If he is evil, then blowing the horn has the effect of a <i>magic circle against good</i>. In either case, this ward lasts for 1 hour. The horn can be blown once per day.</p><p>Faint abjuration; CL 6th; Craft Wondrous Item, <i>magic circle against good</i>,  <i>magic circle against evil</i>; Price 6,500 gp; Weight 1 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1431,'Horn of the Tritons','Wondrous',NULL,'No','Moderate conjuration and transmutation','8','15,100 gp',NULL,'Craft Wondrous Item, fear, summon monster V, control water, creator must be a triton or get construction aid from a triton',NULL,'2 lb','\n      <div topic=\"Horn of the Tritons\" level=\"8\"><p><b>Horn of the Tritons:</b> This device is a conch shell that can be blown once per day except by a triton which can sound it three times per day. A <i>horn of the tritons</i> can perform any one of the following functions when blown.</p><ul>\n <li> Calm rough waters in a 1-mile radius. This effect dispels a summoned water elemental if it fails a DC 16 Will save.</li>\n <li> Attract 5d4 Large sharks (01-30 on d%), 5d6 Medium sharks (31-80), or 1d10 sea lions (81-100) if the character is in a body of water in which such creatures dwell. The creatures are friendly and obey, to the best of their ability, the one who sounded the horn.</li>\n <li> Causes aquatic creatures with Intelligence scores of 1 or 2 within 500 feet to become panicked as if they had been targeted by a <i>fear</i> spell (Will DC 16 partial). Those who successfully save are shaken for 3d6 rounds.</li>\n</ul><p>Any sounding of a <i>horn of the tritons</i> can be heard by all tritons within a 3-mile radius.</p><p>Moderate conjuration and transmutation; CL 8th; Craft Wondrous Item, <i>fear</i>,  <i>summon monster V</i>,  <i>control water</i>,  creator must be a triton or get construction aid from a triton; Price 15,100 gp; Weight 2 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1432,'Horn of Valhalla','Wondrous',NULL,'No','Strong conjuration','13','50,000 gp',NULL,'Craft Wondrous Item, summon monster VI',NULL,'2 lb','\n      <div topic=\"Horn of Valhalla\" level=\"8\"><p><b>Horn of Valhalla:</b> This magic instrument comes in four varieties. Each appears to be normal until someone speaks its command word and blows the horn. Then the horn summons a number of human barbarians to fight for the character who summoned them. Each horn can be blown just once every seven days. Roll d% and refer to the table below to see what type of horn is found. The horn\'s type determines what barbarians are summoned and what prerequisite is needed to use the horn. Any character who uses a <i>horn of Valhalla</i> but doesn\'t have the prerequisite is attacked by the barbarians she herself summoned.</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"5\" curcol=\"5\">\n<td><b>d%</b><br/></td> <td><b>Type of Horn</b><br/></td>\n<td><b>Barbarians Summoned</b><br/></td>\n<td><b>Prerequisite</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"5\" curcol=\"5\">\n<td>01-40<br/></td>\n<td>Silver<br/></td>\n<td>2d4+2, 2nd level<br/></td>\n<td>None<br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>41-75<br/></td>\n<td>Brass<br/></td>\n<td>2d4+1, 3rd level<br/></td>\n<td>Spellcaster level 1st<br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>76-90<br/></td>\n<td>Bronze<br/></td>\n<td>2d4, 4th level<br/></td>\n<td>Proficiency with all martial weapons or bardic music ability<br/></td>\n\n</tr>\n\n<tr maxcol=\"5\" curcol=\"5\">\n<td>91-100<br/></td>\n<td>Iron<br/></td>\n<td>1d4+1, 5th level<br/></td>\n<td>Proficiency with all martial weapons or bardic music ability<br/></td>\n\n</tr>\n</table><p>Summoned barbarians are constructs, not actual people (though they seem to be); they arrive with the starting equipment for barbarians. They attack anyone the possessor of the horn commands them to fight until they or their opponents are slain or until 1 hour has elapsed, whichever comes first.</p><p>Strong conjuration; CL 13th; Craft Wondrous Item, <i>summon monster VI</i>; Price 50,000 gp; Weight 2 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1433,'Horseshoes of Speed','Wondrous',NULL,'No','Faint transmutation','3','3,000 gp',NULL,'Craft Wondrous Item, haste',NULL,'12 lb. (for four)','\n      <div topic=\"Horseshoes of Speed\" level=\"8\"><p><b>Horseshoes of Speed:</b> These iron shoes come in sets of four like ordinary horseshoes. When affixed to an animal\'s hooves, they increase the animal\'s base land speed by 30 feet; this counts as an enhancement bonus. As with other effects that increase speed, jumping distances increase proportionally. All four shoes must be worn by the same animal for the magic to be effective.</p><p>Faint transmutation; CL 3rd; Craft Wondrous Item, <i>haste</i>; Price 3,000 gp; Weight 12 lb. (for four).</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1434,'Horseshoes of A Zephyr','Wondrous',NULL,'No','Faint transmutation','3','6,000 gp',NULL,'Craft Wondrous Item, levitate',NULL,'4 lb. (for four)','\n      <div topic=\"Horseshoes of A Zephyr\" level=\"8\"><p><b>Horseshoes of a Zephyr:</b> These four iron shoes are affixed like normal horseshoes. They allow a horse to travel without actually touching the ground. The horse must still run above (always around 4 inches above) a roughly horizontal surface. This means that nonsolid or unstable surfaces can be crossed, and that movement is possible without leaving tracks on any sort of ground. The horse moves at its normal base land speed. All four shoes must be worn by the same animal for the magic to be effective.</p><p>Faint transmutation; CL 3rd; Craft Wondrous Item, <i>levitate</i>; Price 6,000 gp; Weight 4 lb. (for four).</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1435,'Incense of Meditation','Wondrous',NULL,'No','Moderate enchantment','7','4,900 gp',NULL,'Craft Wondrous Item, Maximize Spell, bless',NULL,'1 lb','\n      <div topic=\"Incense of Meditation\" level=\"8\"><p><b>Incense of Meditation:</b> This small rectangular block of sweet smelling incense is visually indistinguishable from nonmagical incense until lit. When it is burning, the special fragrance and pearly-hued smoke of this special incense are recognizable by anyone making a DC 15 Spellcraft check.</p><p>When a divine spellcaster lights a block of <i>incense of meditation</i> and then spends 8 hours praying and meditating nearby, the incense enables him to prepare all his spells as though affected by the Maximize Spell feat. However, all the spells prepared in this way are at their normal level, not at three levels higher (as with the regular metamagic feat).</p><p>Each block of incense burns for 8 hours, and the effects persist for 24 hours.</p><p>Moderate enchantment; CL 7th; Craft Wondrous Item, Maximize Spell, <i>bless</i>; Price 4,900 gp; Weight 1 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1436,'Instant Fortress','Wondrous',NULL,'No','Strong conjuration','13','55,000 gp',NULL,'Craft Wondrous Item, mage\'s magnificent mansion',NULL,NULL,'\n      <div topic=\"Instant Fortress\" level=\"8\"><p><b>Instant Fortress:</b> This metal cube is small, but when activated by speaking a command word it grows to form a tower 20 feet square and 30 feet high, with arrow slits on all sides and a crenellated battlement atop it. The metal walls extend 10 feet into the ground, rooting it to the spot and preventing it from being tipped over. The fortress has a small door that opens only at the command of the owner of the fortress-even <i>knock</i> spells can\'t open the door.</p><p>The adamantine walls of <i>instant fortress</i> have 100 hit points and hardness 20. The fortress cannot be repaired except by a <i>wish</i> or a <i>miracle</i>, which restores 50 points of damage taken.</p><p>The fortress springs up in just 1 round, with the door facing the device\'s owner. The door opens and closes instantly at his command. People and creatures nearby (except the owner) must be careful not to be caught by the fortress\'s sudden growth. Anyone so caught takes 10d10 points of damage (Reflex DC 19 half ).</p><p>The fortress is deactivated by speaking a command word (different from the one used to activate it). It cannot be deactivated unless it is empty.</p><p>Strong conjuration; CL 13th; Craft Wondrous Item, <i>mage\'s magnificent mansion</i>; Price 55,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1437,'Ioun Stones','Wondrous',NULL,'No','Moderate varied','12',NULL,NULL,'Craft Wondrous Item, creator must be 12th level',NULL,NULL,'\n      <div topic=\"Ioun Stones\" level=\"8\"><p><b>Ioun Stones:</b> These crystalline stones always float in the air and must be within 3 feet of their owner to be of any use. When a character first acquires a stone, she must hold it and then release it, whereupon it takes up a circling orbit 1d3 feet from her head. Thereafter, a stone must be grasped or netted to separate it from its owner. The owner may voluntarily seize and stow a stone (to keep it safe while she is sleeping, for example), but she loses the benefits of the stone during that time. <i>Ioun stones</i> have AC 24, 10 hit points, and hardness 5.</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"5\" curcol=\"5\">\n<td><b>Color</b><br/></td>\n<td><b>Shape</b><br/></td>\n<td><b>Effect</b><br/></td>\n<td><b>Market Price</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"5\" curcol=\"5\">\n<td>Clear<br/></td>\n<td>Spindle<br/></td>\n<td>Sustains creature without food or water<br/></td>\n<td>4,000 gp<br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>Dusty rose<br/></td>\n<td>Prism<br/></td>\n<td>+1 insight bonus to AC<br/></td>\n<td>5,000 gp<br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>Deep red<br/></td>\n<td>Sphere<br/></td>\n<td>+2 enhancement bonus to Dexterity<br/></td>\n<td>8,000 gp<br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>Incandescent blue<br/></td>\n<td>Sphere<br/></td>\n<td>+2 enhancement bonus to Wisdom<br/></td>\n<td>8,000 gp<br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>Pale blue<br/></td>\n<td>Rhomboid<br/></td>\n<td>+2 enhancement bonus to Strength<br/></td>\n<td>8,000 gp<br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>Pink<br/></td>\n<td>Rhomboid<br/></td>\n<td>+2 enhancement bonus to Constitution<br/></td>\n<td>8,000 gp<br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>Pink and green<br/></td>\n<td>Sphere<br/></td>\n<td>+2 enhancement bonus to Charisma<br/></td>\n<td>8,000 gp<br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>Scarlet and blue<br/></td>\n<td>Sphere<br/></td>\n<td>+2 enhancement bonus to Intelligence<br/></td>\n<td>8,000 gp<br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>Dark blue<br/></td>\n<td>Rhomboid<br/></td>\n<td>Alertness (as the feat)<br/></td>\n<td>10,000 gp<br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>Vibrant purple<br/></td>\n<td>Prism<br/></td>\n<td>Stores three levels of spells, as a <i>ring of spell storing</i><br/></td>\n<td>36,000 gp<br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>Iridescent<br/></td>\n<td>Spindle<br/></td>\n<td>Sustains creature without air<br/></td>\n<td>18,000 gp<br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>Pale lavender<br/></td>\n<td>Ellipsoid<br/></td>\n<td>Absorbs spells of 4th level or lower<sup><b>1</b></sup><br/></td>\n<td>20,000 gp<br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>Pearly white<br/></td>\n<td>Spindle<br/></td>\n<td>Regenerate 1 point of damage per hour<br/></td>\n<td>20,000 gp<br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>Pale green<br/></td>\n<td>Prism<br/></td>\n<td>+1 competence bonus on attack rolls, saves, skill checks, and ability checks<br/></td>\n<td>30,000 gp<br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>Orange<br/></td>\n<td>Prism<br/></td>\n<td>+1 caster level<br/></td>\n<td>30,000 gp<br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>Lavender and green<br/></td>\n<td>Ellipsoid<br/></td>\n<td>Absorbs spells of 8th level or lower<sup><b>2</b></sup><br/></td>\n<td>40,000 gp<br/></td>\n\n</tr>\n\n<tr maxcol=\"5\" curcol=\"2\">\n<td colspan=\"4\">1 After absorbing twenty spell levels, the stone burns out and turns to dull gray, forever useless.<br/></td>\n\n</tr>\n\n<tr maxcol=\"5\" curcol=\"2\">\n<td colspan=\"4\">2 After absorbing fifty spell levels, the stone burns out and turns dull gray, forever useless.<br/></td>\n\n</tr>\n</table><p>Regeneration from the pearly white <i>ioun stone</i> works like a <i>ring of regeneration</i>. (It only cures damage taken while the character is using the stone.) The pale lavender and lavender and green stones work like a <i>rod of absorption</i>,  but absorbing a spell requires a readied action, and these stones cannot be used to empower spells. Stored spells in the vibrant purple stone must be placed by a spellcaster but can be used by anyone (see <i>ring of minor spell storing</i>).</p><p>Moderate varied; CL 12th; Craft Wondrous Item, creator must be 12th level.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1438,'Iron Bands of Binding','Wondrous',NULL,'No','Strong evocation','13','26,000 gp',NULL,'Craft Wondrous Item, grasping hand',NULL,'1 lb','\n      <div topic=\"Iron Bands of Binding\" level=\"8\"><p><b>Iron Bands of Binding:</b> When initially discovered, this very potent item appears to be a 3-inch-diameter rusty iron sphere with bandings on the globe.</p><p>When the proper command word is spoken and the spherical iron device is hurled at an opponent, the bands expand and then contract to bind the target creature on a successful ranged touch attack. A single Large or smaller creature can be captured thus and held immobile until the command word is spoken to bring the bands into spherical form again. The creature can break (and ruin) the bands with a DC 30 Strength check or escape them with a DC 30 Escape Artist check. <i>Iron bands of binding</i> are usable once per day.</p><p>Strong evocation; CL 13th; Craft Wondrous Item, <i>grasping hand</i>; Price 26,000 gp; Weight 1 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1439,'Iron Flask','Wondrous',NULL,'No','Strong conjuration','20','170,000 gp (empty)',NULL,'Craft Wondrous Item, trap the soul',NULL,'1 lb','\n      <div topic=\"Iron Flask\" level=\"8\"><p><b>Iron Flask:</b> These special containers are typically inlaid with runes of silver and stoppered by a brass plug bearing a seal engraved with sigils, glyphs, and special symbols. When the user speaks the command word, he can force any creature from another plane into the container, provided that creature fails a DC 19 Will save. The range of this effect is 60 feet. Only one creature at a time can be so contained. Loosing the stopper frees the captured creature.</p><p>The command word can be given only once per day.</p><p>If the individual freeing the captured creature speaks the command word, the creature can be forced to serve for 1 hour. If freed without the command word, the creature acts according to its natural inclinations. (It usually attacks the user, unless it perceives a good reason not to.) Any attempt to force the same creature into the flask a second time provides it a +2 bonus on its saving throw and makes it hostile. A newly discovered bottle might contain any of the following:</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"5\" curcol=\"5\">\n<td><b>d%</b><br/></td>\n<td><b>Contents</b><br/></td>\n<td><b>d%</b><br/></td>\n<td><b>Contents</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"5\" curcol=\"5\">\n<td>01-50<br/></td>\n<td>Empty<br/></td>\n<td>89<br/></td>\n<td>Demon (glabrezu)<br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>51-54<br/></td>\n<td>Large air elemental<br/></td>\n<td>90<br/></td>\n<td>Demon (succubus)<br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>55-58<br/></td>\n<td>Arrowhawk<br/></td>\n<td>91<br/></td>\n<td>Devil (osyluth)<br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>59-62<br/></td>\n<td>Large earth elemental<br/></td>\n<td>92<br/></td>\n<td>Devil (barbazu)<br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>63-66<br/></td>\n<td>Xorn<br/></td>\n<td>93<br/></td>\n<td>Devil (erinyes)<br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>67-70<br/></td>\n<td>Large fire elemental<br/></td>\n<td>94<br/></td>\n<td>Devil (cornugon)<br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>71-74<br/></td>\n<td>Salamander<br/></td>\n<td>95<br/></td>\n<td>Celestial (avoral)<br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>75-78<br/></td>\n<td>Large water elemental<br/></td>\n<td>96<br/></td>\n<td>Celestial (ghaele)<br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>79-82<br/></td>\n<td>Adult tojanida<br/></td>\n<td>97<br/></td>\n<td>Formian myrmarch<br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>83-84<br/></td>\n<td>Chaos Beast<br/></td>\n<td>98<br/></td>\n<td>Arrowhawk, elder<br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>85-86<br/></td>\n<td>Formian taskmaster<br/></td>\n<td>99<br/></td>\n<td>Rakshasa<br/></td>\n\n</tr>\n\n<tr maxcol=\"5\" curcol=\"5\">\n<td>87<br/></td>\n<td>Demon (vrock)<br/></td>\n<td>100<br/></td>\n<td>Demon (balor) or devil (pit fiend)-equal chance for either<br/></td>\n\n</tr>\n\n<tr maxcol=\"5\" curcol=\"5\">\n<td>88<br/></td>\n<td>Demon (hezrou)<br/></td>\n<td/>\n<td/>\n\n</tr>\n</table><p>Strong conjuration; CL 20th; Craft Wondrous Item, <i>trap the soul</i>; Price 170,000 gp (empty); Weight 1 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1440,'Lantern of Revealing','Wondrous',NULL,'No','Faint evocation','5','30,000 gp',NULL,'Craft Wondrous Item, invisibility purge',NULL,'2 lb','\n      <div topic=\"Lantern of Revealing\" level=\"8\"><p><b>Lantern of Revealing:</b> This lantern operates as a normal hooded lantern. While it is lit, it also reveals all invisible creatures and objects within 25 feet of it, just like the spell <i>invisibility purge</i>.</p><p>Faint evocation; CL 5th; Craft Wondrous Item, <i>invisibility purge</i>; Price 30,000 gp; Weight 2 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1441,'Lens of Detection','Wondrous',NULL,'No','Moderate divination','9','3,500 gp',NULL,'Craft Wondrous Item, true seeing',NULL,'1 lb','\n      <div topic=\"Lens of Detection\" level=\"8\"><p><b>Lens of Detection:</b> This circular prism enables its user to detect minute details, granting a +5 bonus on Search checks.</p><p>It also aids in following tracks, adding a +5 bonus on Survival checks when tracking. The lens is about 6 inches in diameter and set in a frame with a handle.</p><p>Moderate divination; CL 9th; Craft Wondrous Item, <i>true seeing</i>; Price 3,500 gp; Weight 1 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1442,'Lyre of Building','Wondrous',NULL,'No','Faint transmutation','6','13,000 gp',NULL,'Craft Wondrous Item, fabricate',NULL,'5 lb','\n      <div topic=\"Lyre of Building\" level=\"8\"><p><b>Lyre of Building:</b> If the proper chords are struck, a single use of this lyre negates any attacks made against all inanimate construction (walls, roof, floor, and so on) within 300 feet. This includes the effects of a <i>horn of blasting</i>,  a <i>disintegrate</i> spell, or an attack from a ram or similar siege weapon. The lyre can be used in this way once per day, with the protection lasting for 30 minutes.</p><p>The lyre is also useful with respect to building. Once a week its strings can be strummed so as to produce chords that magically construct buildings, mines, tunnels, ditches, or whatever. The effect produced in but 30 minutes of playing is equal to the work of 100 humans laboring for three days. Each hour after the first, a character playing the lyre must make a DC 18 Perform (string instruments) check. If it fails, she must stop and cannot play the lyre again for this purpose until a week has passed.</p><p>Faint transmutation; CL 6th; Craft Wondrous Item, <i>fabricate</i>; Price 13,000 gp; Weight 5 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1443,'Mantle of Faith','Wondrous',NULL,'No','Strong abjuration [good]','20','76,000 gp',NULL,'Craft Wondrous Item, stoneskin',NULL,NULL,'\n      <div topic=\"Mantle of Faith\" level=\"8\"><p><b>Mantle of Faith:</b> This holy garment, worn over normal clothing, grants damage reduction 5/evil to the character wearing it.</p><p>Strong abjuration [good]; CL 20th; Craft Wondrous Item, <i>stoneskin</i>; Price 76,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1444,'Mantle of Spell Resistance','Wondrous',NULL,'No','Moderate abjuration','9','90,000 gp',NULL,'Craft Wondrous Item, spell resistance',NULL,NULL,'\n      <div topic=\"Mantle of Spell Resistance\" level=\"8\"><p><b>Mantle of Spell Resistance:</b> This garment, worn over normal clothing or armor, grants the wearer spell resistance 21.</p><p>Moderate abjuration; CL 9th; Craft Wondrous Item, <i>spell resistance</i>; Price 90,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1445,'Manual of Bodily Health +1','Wondrous',NULL,'No','Strong evocation (if miracle is used)','17','27,500 gp',NULL,'Craft Wondrous Item, wish or miracle','1,250 gp + 5,100 XP','5 lb','\n      <div topic=\"Manual of Bodily Health\" level=\"8\"><p><b>Manual of Bodily Health:</b> This thick tome contains tips on health and fitness, but entwined within the words is a powerful magical effect. If anyone reads this book, which takes a total of 48 hours over a minimum of six days, he gains an inherent bonus of from +1 to +5 (depending on the type of manual) to his Constitution score. Once the book is read, the magic disappears from the pages and it becomes a normal book.</p><p>Strong evocation (if <i>miracle</i> is used); CL 17th; Craft Wondrous Item, <i>wish</i> or <i>miracle</i>; Price 27,500 gp (+1), 55,000 gp (+2), 82,500 gp (+3), 110,000 gp (+4), 137,500 gp (+5); Cost 1,250 gp + 5,100 XP (+1), 2,500 gp + 10,200 XP (+2), 3,750 gp + 15,300 XP (+3), 5,000 gp + 20,400 XP (+4), 6,250 gp + 25,500 XP (+5); Weight 5 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
