INSERT INTO item VALUES (1457,'Manual of Quickness of Action +3','Wondrous',NULL,'No','Strong evocation (if miracle is used)','17','82,500 gp',NULL,'Craft Wondrous Item, wish or miracle','3,750 gp + 15,300 XP','5 lb','\n      <div topic=\"Manual of Quickness of Action\" level=\"8\"><p><b>Manual of Quickness of Action:</b> This thick tome contains tips on coordination exercises and balance, but entwined within the words is a powerful magical effect. If anyone reads this book, which takes a total of 48 hours over a minimum of six days, he gains an inherent bonus of from +1 to +5 (depending on the type of manual) to his Dexterity score. Once the book is read, the magic disappears from the pages and it becomes a normal book.</p><p>Strong evocation (if <i>miracle</i> is used); CL 17th; Craft Wondrous Item, <i>wish</i> or <i>miracle</i>; Price 27,500 gp (+1), 55,000 gp (+2), 82,500 gp (+3), 110,000 gp (+4), 137,500 gp (+5); Cost 1,250 gp + 5,100 XP (+1), 2,500 gp + 10,200 XP (+2), 3,750 gp + 15,300 XP (+3), 5,000 gp + 20,400 XP (+4), 6,250 gp + 25,500 XP (+5); Weight 5 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1458,'Manual of Quickness of Action +4','Wondrous',NULL,'No','Strong evocation (if miracle is used)','17','110,000 gp',NULL,'Craft Wondrous Item, wish or miracle','5,000 gp + 20,400 XP','5 lb','\n      <div topic=\"Manual of Quickness of Action\" level=\"8\"><p><b>Manual of Quickness of Action:</b> This thick tome contains tips on coordination exercises and balance, but entwined within the words is a powerful magical effect. If anyone reads this book, which takes a total of 48 hours over a minimum of six days, he gains an inherent bonus of from +1 to +5 (depending on the type of manual) to his Dexterity score. Once the book is read, the magic disappears from the pages and it becomes a normal book.</p><p>Strong evocation (if <i>miracle</i> is used); CL 17th; Craft Wondrous Item, <i>wish</i> or <i>miracle</i>; Price 27,500 gp (+1), 55,000 gp (+2), 82,500 gp (+3), 110,000 gp (+4), 137,500 gp (+5); Cost 1,250 gp + 5,100 XP (+1), 2,500 gp + 10,200 XP (+2), 3,750 gp + 15,300 XP (+3), 5,000 gp + 20,400 XP (+4), 6,250 gp + 25,500 XP (+5); Weight 5 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1459,'Manual of Quickness of Action +5','Wondrous',NULL,'No','Strong evocation (if miracle is used)','17','137,500 gp',NULL,'Craft Wondrous Item, wish or miracle','6,250 gp + 25,500 XP','5 lb','\n      <div topic=\"Manual of Quickness of Action\" level=\"8\"><p><b>Manual of Quickness of Action:</b> This thick tome contains tips on coordination exercises and balance, but entwined within the words is a powerful magical effect. If anyone reads this book, which takes a total of 48 hours over a minimum of six days, he gains an inherent bonus of from +1 to +5 (depending on the type of manual) to his Dexterity score. Once the book is read, the magic disappears from the pages and it becomes a normal book.</p><p>Strong evocation (if <i>miracle</i> is used); CL 17th; Craft Wondrous Item, <i>wish</i> or <i>miracle</i>; Price 27,500 gp (+1), 55,000 gp (+2), 82,500 gp (+3), 110,000 gp (+4), 137,500 gp (+5); Cost 1,250 gp + 5,100 XP (+1), 2,500 gp + 10,200 XP (+2), 3,750 gp + 15,300 XP (+3), 5,000 gp + 20,400 XP (+4), 6,250 gp + 25,500 XP (+5); Weight 5 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1460,'Marvelous Pigments','Wondrous',NULL,'No','Strong conjuration','15','4,000 gp',NULL,'Craft Wondrous Item, major creation',NULL,NULL,'\n      <div topic=\"Marvelous Pigments\" level=\"8\"><p><b>Marvelous Pigments:</b> These magic emulsions enable their possessor to create actual, permanent objects simply by depicting their form in two dimensions. The pigments are applied by a stick tipped with bristles, hair, or fur. The emulsion flows from the application to form the desired object as the artist concentrates on the desired image. One pot of <i>Marvelous pigments</i> is sufficient to create a 1,000-cubic-foot object by depicting it two-dimensionally over a 100-square-foot surface.</p><p>Only normal, inanimate objects can be created. Creatures can\'t be created. The pigments must be applied to a surface. It takes 10 minutes and a DC 15 Craft (painting) check to depict an object with the pigments. <i>Marvelous pigments</i> cannot create magic items. Objects of value depicted by the pigments -precious metals, gems, jewelry, ivory, and so on- appear to be valuable but are really made of tin, lead, paste, brass, bone, and other such inexpensive materials. The user can create normal weapons, armor, and any other mundane item (including foodstuffs) whose value does not exceed 2,000 gp.</p><p>Items created are not magical; the effect is instantaneous.</p><p>Strong conjuration; CL 15th; Craft Wondrous Item, <i>major creation</i>; Price 4,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1461,'Mask of the Skull','Wondrous',NULL,'No','Strong necromancy and transmutation','13','22,000 gp',NULL,'Craft Wondrous Item, animate objects, finger of death, fly',NULL,'3 lb','\n      <div topic=\"Mask of the Skull\" level=\"8\"><p><b>Mask of the Skull:</b> This ivory mask has been fashioned into the likeness of a human skull. Once per day, after it has been worn for at least 1 hour, the mask can be loosed to fly from the wearer\'s face. It travels up to 50 feet away from the wearer and attacks a target assigned to it. The grinning skull mask makes a touch attack against the target based on the wearer\'s base attack bonus. If the attack succeeds, the target must make a DC 20 Fortitude save or be struck dead, as if affected by a <i>finger of death</i> spell. If the target succeeds on his saving throw, he nevertheless takes 3d6+13 points of damage. After attacking (whether successful or not), the mask flies back to its user. The mask has AC 16, 10 hit points, and hardness 6.</p><p>Strong necromancy and transmutation; CL 13th; Craft Wondrous Item, <i>animate objects</i>,  <i>finger of death</i>,  <i>fly</i>; Price 22,000 gp; Weight 3 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1462,'Mattock of the Titans','Wondrous',NULL,'No','Strong transmutation','16','23,348 gp',NULL,'Craft Wondrous Item, Craft Magic Arms and Armor, move earth','13,348 gp + 800 XP','120 lb','\n      <div topic=\"Mattock of the Titans\" level=\"8\"><p><b>Mattock of the Titans:</b> This digging tool is 10 feet long. Any creature of at least Huge size can use it to loosen or tumble earth or earthen ramparts (a 10-foot cube every 10 minutes). It also smashes rock (a 10-foot cube per hour). If used as a weapon, it is the equivalent of a Gargantuan <i>+3 adamantine warhammer</i>,  dealing 4d6 points of base damage.</p><p>Strong transmutation; CL 16th; Craft Wondrous Item, Craft Magic Arms and Armor, <i>move earth</i>; Price 23,348 gp; Cost 13,348 gp + 800 XP; Weight 120 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1463,'Maul of the Titans','Wondrous',NULL,'No','Strong evocation','15','25,305 gp',NULL,'Craft Wondrous Item, Craft Magic Arms and Armor, clenched fist','12,305 gp + 480 XP','160 lb','\n      <div topic=\"Maul of the Titans\" level=\"8\"><p><b>Maul of the Titans:</b> This mallet is 8 feet long. If used as a weapon, it is the equivalent of a <i>+3 greatclub</i> and deals triple damage against inanimate objects. However, the wielder must have a Strength of at least 18 to wield it properly. Otherwise, she takes a -4 penalty on attack rolls.</p><p>Strong evocation; CL 15th; Craft Wondrous Item, Craft Magic Arms and Armor, <i>clenched fist</i>; Price 25,305 gp; Cost 12,305 gp + 480 XP; Weight 160 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1464,'Medallion of Thoughts','Wondrous',NULL,'No','Faint divination','5','12,000 gp',NULL,'Craft Wondrous Item, detect thoughts',NULL,NULL,'\n      <div topic=\"Medallion of Thoughts\" level=\"8\"><p><b>Medallion of Thoughts:</b> This appears to be a normal pendant disk hung from a neck chain. Usually fashioned from bronze, copper, or nickel-silver, the medallion allows the wearer to read the thoughts of others, as with the spell <i>detect thoughts</i>.</p><p>Faint divination; CL 5th; Craft Wondrous Item, <i>detect thoughts</i>; Price 12,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1465,'Mirror of Life Trapping','Wondrous',NULL,'No','Strong abjuration','17','200,000 gp',NULL,'Craft Wondrous Item, imprisonment',NULL,'50 lb','\n      <div topic=\"Mirror of Life Trapping\" level=\"8\"><p><b>Mirror of Life Trapping:</b> This crystal device is usually about 4 feet square and framed in metal or wood. It can be hung or placed on a surface and then activated by giving a command word. The same command word deactivates the mirror. A <i>mirror of life trapping</i> has fifteen nonspatial extradimensional compartments within it. Any creature coming within 30 feet of the device and looking at its own reflection must make a DC 23 Will save or be trapped within the mirror in one of the cells. A creature not aware of the nature of the device always sees its own reflection. The probability of a creature seeing its reflection, and thus needing to make the saving throw, drops to 50% if the creature is aware that the mirror traps life and seeks to avoid looking at it (treat as a gaze attack).</p><p>When a creature is trapped, it is taken bodily into the mirror. Size is not a factor, but constructs and undead are not trapped, nor are inanimate objects and other nonliving matter. A victim\'s equipment (including clothing and anything being carried) remains behind. If the mirror\'s owner knows the right command word, he can call the reflection of any creature trapped within to its surface and engage his powerless prisoner in conversation. Another command word frees the trapped creature. Each pair of command words is specific to each prisoner.</p><p>If the mirror\'s capacity is exceeded, one victim (determined randomly) is set free in order to accommodate the latest one. If the mirror is broken, all victims currently trapped in it are freed.</p><p>Strong abjuration; CL 17th; Craft Wondrous Item, <i>imprisonment</i>; Price 200,000 gp; Weight 50 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1466,'Mirror of Mental Prowess','Wondrous',NULL,'No','Strong conjuration and divination','17','175,000 gp',NULL,'Craft Wondrous Item, detect thoughts, clairaudience/clairvoyance, gate, legend lore',NULL,'40 lb','\n      <div topic=\"Mirror of Mental Prowess\" level=\"8\"><p><b>Mirror of Mental Prowess:</b> This mirror resembles an ordinary looking glass 5 feet tall by 2 feet wide. The possessor who knows the proper commands can cause it to perform as follows.</p><ul>\n <li> Read the thoughts of any creature reflected therein, as long as the owner is within 25 feet of the mirror, even if those thoughts are in an unknown language.</li>\n <li> View other places as if with <i>clairvoyance</i>,  but vision extends even onto other planes if the viewer is sufficiently familiar with them.</li>\n <li> Use it as a portal to visit other places. The user first views the place with the <i>clairvoyance</i> function, then steps through the mirror to the place pictured. Others can follow her through the mirror if they like. An invisible portal remains on the other side where she arrives, and she can return through that portal. Once she returns, the portal closes. The portal closes on its own after 24 hours (trapping the user if she\'s still in the other place), and the user can also close it with a command word. Creatures with Intelligence of 12 or higher might notice the portal just as they might notice a magical sensor from a <i>scrying</i> spell. Any creature who steps through the portal appears in front of the mirror.</li>\n <li> Once per week the mirror accurately answers one short question regarding a creature whose image is shown on its surface (giving answers similar to those from the <i>legend lore</i> spell).</li>\n</ul><p>Strong conjuration and divination; CL 17th; Craft Wondrous Item, <i>detect thoughts</i>, <i>clairaudience/clairvoyance</i>,  <i>gate</i>,  <i>legend lore</i>; Price 175,000 gp; Weight 40 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1467,'Mirror of Opposition','Wondrous',NULL,'No','Strong necromancy','15','92,000 gp',NULL,'Craft Wondrous Item, clone',NULL,'45 lb','\n      <div topic=\"Mirror of Opposition\" level=\"8\"><p><b>Mirror of Opposition:</b> This item resembles a normal mirror about 4 feet long and 3 feet wide. It can be hung or placed on a surface and then activated by speaking a command word. The same command word deactivates the mirror. If a creature sees its reflection in the mirror\'s surface, an exact duplicate of that creature comes into being. This opposite immediately attacks the original. The duplicate has all the possessions and powers of its original (including magic). Upon the defeat or destruction of either the duplicate or the original, the duplicate and her items disappear completely. The mirror functions up to four times per day.</p><p>Strong necromancy; CL 15th; Craft Wondrous Item, <i>clone</i>; Price 92,000 gp; Weight 45 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1468,'Necklace of Adaptation','Wondrous',NULL,'No','Moderate transmutation','7','9,000 gp',NULL,'Craft Wondrous Item, alter self',NULL,NULL,'\n      <div topic=\"Necklace of Adaptation\" level=\"8\"><p><b>Necklace of Adaptation:</b> This necklace is a heavy chain with a platinum medallion. The magic of the necklace wraps the wearer in a shell of fresh air, making him immune to all harmful vapors and gases (such as <i>cloudkill</i> and <i>stinking cloud</i> effects, as well as inhaled poisons) and allowing him to breathe, even underwater or in a vacuum.</p><p>Moderate transmutation; CL 7th; Craft Wondrous Item, <i>alter self</i>; Price 9,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1469,'Necklace of Fireballs','Wondrous',NULL,'No','Moderate evocation','10',NULL,NULL,'Craft Wondrous Item, fireball',NULL,NULL,'\n      <div topic=\"Necklace of Fireballs\" level=\"8\"><p><b>Necklace of Fireballs:</b> This device appears to be nothing but beads on a string, sometimes with the ends tied together to form a necklace. (It does not count as an item worn around the neck for the purpose of determining which of a character\'s worn magic items is effective.) If a character holds it, however, all can see the strand as it really is-a golden chain from which hang a number of golden spheres. The spheres are detachable by the wearer (and only by the wearer), who can easily hurl one of them up to 70 feet. When a sphere arrives at the end of its trajectory, it detonates as a <i>fireball</i> spell (Reflex DC 14 half ).</p><p>Spheres come in different strengths, ranging from those that deal 2d6 points of fire damage to those that deal 10d6. The market price of a sphere is 150 gp for each die of damage it deals.</p><p>Each <i>necklace of fireballs</i> contains a combination of spheres of various strengths. Some traditional combinations, designated types I through VII, are detailed below.</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"12\" curcol=\"12\">\n<td><b>Necklace</b><br/></td>\n<td><b>10d6</b><br/></td>\n<td><b>9d6</b><br/></td>\n<td><b>8d6</b><br/></td>\n<td><b>7d6</b><br/></td>\n<td><b>6d6</b><br/></td>\n<td><b>5d6</b><br/></td>\n<td><b>4d6</b><br/></td>\n<td><b>3d6</b><br/></td>\n<td><b>2d6</b><br/></td>\n<td><b>Market Price</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"12\" curcol=\"12\">\n<td>Type I<br/></td>\n<td>-<br/></td>\n<td>-<br/></td>\n<td>-<br/></td>\n<td>-<br/></td>\n<td>-<br/></td>\n<td>1<br/></td>\n<td>-<br/></td>\n<td>2<br/></td>\n<td>-<br/></td>\n<td>1,650 gp<br/></td>\n\n</tr>\n<tr maxcol=\"12\" curcol=\"12\">\n<td>Type II<br/></td>\n<td>-<br/></td>\n<td>-<br/></td>\n<td>-<br/></td>\n<td>-<br/></td>\n<td>1<br/></td>\n<td>-<br/></td>\n<td>2<br/></td>\n<td>-<br/></td>\n<td>2<br/></td>\n<td>2,700 gp<br/></td>\n\n</tr>\n<tr maxcol=\"12\" curcol=\"12\">\n<td>Type III<br/></td>\n<td>-<br/></td>\n<td>-<br/></td>\n<td>-<br/></td>\n<td>1<br/></td>\n<td>-<br/></td>\n<td>2<br/></td>\n<td>-<br/></td>\n<td>4<br/></td>\n<td>-<br/></td>\n<td>4,350 gp<br/></td>\n\n</tr>\n<tr maxcol=\"12\" curcol=\"12\">\n<td>Type IV<br/></td>\n<td>-<br/></td>\n<td>-<br/></td>\n<td>1<br/></td>\n<td>-<br/></td>\n<td>2<br/></td>\n<td>-<br/></td>\n<td>2<br/></td>\n<td>-<br/></td>\n<td>4<br/></td>\n<td>5,400 gp<br/></td>\n\n</tr>\n<tr maxcol=\"12\" curcol=\"12\">\n<td>Type V<br/></td>\n<td>-<br/></td>\n<td>1<br/></td>\n<td>-<br/></td>\n<td>2<br/></td>\n<td>-<br/></td>\n<td>2<br/></td>\n<td>-<br/></td>\n<td>2<br/></td>\n<td>-<br/></td>\n<td>5,850 gp<br/></td>\n\n</tr>\n<tr maxcol=\"12\" curcol=\"12\">\n<td>Type VI<br/></td>\n<td>1<br/></td>\n<td>-<br/></td>\n<td>2<br/></td>\n<td>-<br/></td>\n<td>2<br/></td>\n<td>-<br/></td>\n<td>4<br/></td>\n<td>-<br/></td>\n<td>-<br/></td>\n<td>8,100 gp<br/></td>\n\n</tr>\n\n<tr maxcol=\"12\" curcol=\"12\">\n<td>Type VII<br/></td>\n<td>1<br/></td>\n<td>2<br/></td>\n<td>-<br/></td>\n<td>2<br/></td>\n<td>-<br/></td>\n<td>2<br/></td>\n<td>-<br/></td>\n<td>2<br/></td>\n<td>-<br/></td>\n<td>8,700 gp<br/></td>\n\n</tr>\n</table><p>If the necklace is being worn or carried by a character who fails her saving throw against a magical fire attack, the item must make a saving throw as well (with a save bonus of +7). If the necklace fails to save, all its remaining spheres detonate simultaneously, often with regrettable consequences for the wearer.</p><p>Moderate evocation; CL 10th; Craft Wondrous Item, <i>fireball</i>. </p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1470,'Orb of Storms','Wondrous',NULL,'No','Strong varied','18','48,000 gp',NULL,'Craft Wondrous Item, control weather, endure elements, storm of vengeance',NULL,'6 lb','\n      <div topic=\"Orb of Storms\" level=\"8\"><p><b>Orb of Storms:</b> This glass sphere is 8 inches in diameter. The possessor can call forth all manner of weather, even supernaturally destructive storms. Once per day she can call upon the orb to use a <i>control weather</i> spell, Once per month, she can conjure a <i>storm of vengeance</i>. The possessor of the orb is continually protected by an <i>endure elements</i> effect.</p><p>Strong varied; CL 18th; Craft Wondrous Item, <i>control weather</i>,  <i>endure elements</i>,  <i>storm of vengeance</i>; Price 48,000 gp; Weight 6 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1471,'Pearl of Power (1st)','Wondrous',NULL,'No','Strong transmutation','17','1,000 gp',NULL,'Craft Wondrous Item, creator must be able to cast spells of the spell level to be recalled',NULL,NULL,'\n      <div topic=\"Pearl of Power\" level=\"8\"><p><b>Pearl of Power:</b> This seemingly normal pearl of average size and luster is a potent aid to all spellcasters who prepare spells (clerics, druids, rangers, paladins, and wizards). Once per day on command, a <i>pearl of power</i> enables the possessor to recall any one spell that she had prepared and then cast. The spell is then prepared again, just as if it had not been cast. The spell must be of a particular level, depending on the pearl. Different pearls exist for recalling one spell per day of each level from 1st through 9th and for the recall of two spells per day (each of a different level, 6th or lower).</p><p>Strong transmutation; CL 17th; Craft Wondrous Item, creator must be able to cast spells of the spell level to be recalled; Price 1,000 gp (1st), 4,000 gp (2nd), 9,000 gp (3rd), 16,000 gp (4th), 25,000 gp (5th), 36,000 gp (6th), 49,000 gp (7th), 64,000 gp (8th), 81,000 gp (9th), or 70,000 gp (two spells).</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1472,'Pearl of Power (2nd)','Wondrous',NULL,'No','Strong transmutation','17','4,000 gp',NULL,'Craft Wondrous Item, creator must be able to cast spells of the spell level to be recalled',NULL,NULL,'\n      <div topic=\"Pearl of Power\" level=\"8\"><p><b>Pearl of Power:</b> This seemingly normal pearl of average size and luster is a potent aid to all spellcasters who prepare spells (clerics, druids, rangers, paladins, and wizards). Once per day on command, a <i>pearl of power</i> enables the possessor to recall any one spell that she had prepared and then cast. The spell is then prepared again, just as if it had not been cast. The spell must be of a particular level, depending on the pearl. Different pearls exist for recalling one spell per day of each level from 1st through 9th and for the recall of two spells per day (each of a different level, 6th or lower).</p><p>Strong transmutation; CL 17th; Craft Wondrous Item, creator must be able to cast spells of the spell level to be recalled; Price 1,000 gp (1st), 4,000 gp (2nd), 9,000 gp (3rd), 16,000 gp (4th), 25,000 gp (5th), 36,000 gp (6th), 49,000 gp (7th), 64,000 gp (8th), 81,000 gp (9th), or 70,000 gp (two spells).</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
