INSERT INTO item VALUES (1479,'Pearl of Power (9th)','Wondrous',NULL,'No','Strong transmutation','17','81,000 gp',NULL,'Craft Wondrous Item, creator must be able to cast spells of the spell level to be recalled',NULL,NULL,'\n      <div topic=\"Pearl of Power\" level=\"8\"><p><b>Pearl of Power:</b> This seemingly normal pearl of average size and luster is a potent aid to all spellcasters who prepare spells (clerics, druids, rangers, paladins, and wizards). Once per day on command, a <i>pearl of power</i> enables the possessor to recall any one spell that she had prepared and then cast. The spell is then prepared again, just as if it had not been cast. The spell must be of a particular level, depending on the pearl. Different pearls exist for recalling one spell per day of each level from 1st through 9th and for the recall of two spells per day (each of a different level, 6th or lower).</p><p>Strong transmutation; CL 17th; Craft Wondrous Item, creator must be able to cast spells of the spell level to be recalled; Price 1,000 gp (1st), 4,000 gp (2nd), 9,000 gp (3rd), 16,000 gp (4th), 25,000 gp (5th), 36,000 gp (6th), 49,000 gp (7th), 64,000 gp (8th), 81,000 gp (9th), or 70,000 gp (two spells).</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1480,'Pearl of Power, Two Spells','Wondrous',NULL,'No','Strong transmutation','17','or 70,000 gp',NULL,'Craft Wondrous Item, creator must be able to cast spells of the spell level to be recalled',NULL,NULL,'\n      <div topic=\"Pearl of Power\" level=\"8\"><p><b>Pearl of Power:</b> This seemingly normal pearl of average size and luster is a potent aid to all spellcasters who prepare spells (clerics, druids, rangers, paladins, and wizards). Once per day on command, a <i>pearl of power</i> enables the possessor to recall any one spell that she had prepared and then cast. The spell is then prepared again, just as if it had not been cast. The spell must be of a particular level, depending on the pearl. Different pearls exist for recalling one spell per day of each level from 1st through 9th and for the recall of two spells per day (each of a different level, 6th or lower).</p><p>Strong transmutation; CL 17th; Craft Wondrous Item, creator must be able to cast spells of the spell level to be recalled; Price 1,000 gp (1st), 4,000 gp (2nd), 9,000 gp (3rd), 16,000 gp (4th), 25,000 gp (5th), 36,000 gp (6th), 49,000 gp (7th), 64,000 gp (8th), 81,000 gp (9th), or 70,000 gp (two spells).</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1481,'Pearl of the Sirines','Wondrous',NULL,'No','Moderate abjuration and transmutation','8','15,300 gp',NULL,'Craft Wondrous Item, freedom of movement, water breathing',NULL,NULL,'\n      <div topic=\"Pearl of the Sirines\" level=\"8\"><p><b>Pearl of the Sirines:</b> This normal-seeming pearl is beautiful and worth at least 1,000 gp on that basis alone. If it is clasped firmly in hand or held to the breast while the possessor attempts actions related to the pearl\'s powers, she understands and is able to employ the item.</p><p>The pearl enables its possessor to breathe in water as if she were in clean, fresh air. Her swim speed is 60 feet, and she can cast spells and act underwater without hindrance.</p><p>Moderate abjuration and transmutation; CL 8th; Craft Wondrous Item, <i>freedom of movement</i>,  <i>water breathing</i>; Price 15,300 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1482,'Periapt of Health','Wondrous',NULL,'No','Faint conjuration','5','7,500 gp',NULL,'Craft Wondrous Item, remove disease',NULL,NULL,'\n      <div topic=\"Periapt of Health\" level=\"8\"><p><b>Periapt of Health:</b> The wearer of this blue gem on a silver chain is immune to disease, including supernatural diseases.</p><p>Faint conjuration; CL 5th; Craft Wondrous Item, <i>remove disease</i>; Price 7,500 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1483,'Periapt of Proof Against Poison','Wondrous',NULL,'No','Faint conjuration','5','27,000 gp',NULL,'Craft Wondrous Item, neutralize poison',NULL,NULL,'\n      <div topic=\"Periapt of Proof Against Poison\" level=\"8\"><p><b>Periapt of Proof against Poison:</b> This item is a brilliant-cut black gem on a delicate silver chain. The wearer is immune to poison, although poisons still active when the periapt is first donned still run their course.</p><p>Faint conjuration; CL 5th; Craft Wondrous Item, <i>neutralize poison</i>; Price 27,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1484,'Periapt of Wisdom +2','Wondrous',NULL,'No','Moderate transmutation','8','4,000 gp',NULL,'Craft Wondrous Item, owl\'s wisdom',NULL,NULL,'\n      <div topic=\"Periapt of Wisdom\" level=\"8\"><p><b>Periapt of Wisdom:</b> Although it appears to be a normal pearl on a light chain, a <i>periapt of wisdom</i> actually increases the possessor\'s Wisdom score in the form of an enhancement bonus of +2, +4, or +6 (depending on the individual item).</p><p>Moderate transmutation; CL 8th; Craft Wondrous Item, <i>owl\'s wisdom</i>; Price 4,000 gp (+2), 16,000 gp (+4), 36,000 gp (+6).</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1485,'Periapt of Wisdom +4','Wondrous',NULL,'No','Moderate transmutation','8','16,000 gp',NULL,'Craft Wondrous Item, owl\'s wisdom',NULL,NULL,'\n      <div topic=\"Periapt of Wisdom\" level=\"8\"><p><b>Periapt of Wisdom:</b> Although it appears to be a normal pearl on a light chain, a <i>periapt of wisdom</i> actually increases the possessor\'s Wisdom score in the form of an enhancement bonus of +2, +4, or +6 (depending on the individual item).</p><p>Moderate transmutation; CL 8th; Craft Wondrous Item, <i>owl\'s wisdom</i>; Price 4,000 gp (+2), 16,000 gp (+4), 36,000 gp (+6).</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1486,'Periapt of Wisdom +6','Wondrous',NULL,'No','Moderate transmutation','8','36,000 gp',NULL,'Craft Wondrous Item, owl\'s wisdom',NULL,NULL,'\n      <div topic=\"Periapt of Wisdom\" level=\"8\"><p><b>Periapt of Wisdom:</b> Although it appears to be a normal pearl on a light chain, a <i>periapt of wisdom</i> actually increases the possessor\'s Wisdom score in the form of an enhancement bonus of +2, +4, or +6 (depending on the individual item).</p><p>Moderate transmutation; CL 8th; Craft Wondrous Item, <i>owl\'s wisdom</i>; Price 4,000 gp (+2), 16,000 gp (+4), 36,000 gp (+6).</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1487,'Periapt of Wound Closure','Wondrous',NULL,'No','Moderate conjuration','10','15,000 gp',NULL,'Craft Wondrous Item, heal',NULL,NULL,'\n      <div topic=\"Periapt of Wound Closure\" level=\"8\"><p><b>Periapt of Wound Closure:</b> This stone is bright red and dangles on a gold chain. The wearer of this periapt automatically becomes stable if his hit points drop to between -1 and -9 inclusive. The periapt doubles the wearer\'s normal rate of healing or allows normal healing of wounds that would not do so normally. Hit point damage that involves bleeding is negated for the wearer of the periapt, but he is still susceptible to damage from bleeding that causes Constitution loss, such as that dealt by a wounding weapon.</p><p>Moderate conjuration; CL 10th; Craft Wondrous Item, <i>heal</i>; Price 15,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1488,'Phylactery of Faithfulness','Wondrous',NULL,'No','Faint divination','1','1,000 gp',NULL,'Craft Wondrous Item, detect chaos, detect evil, detect good, detect law',NULL,NULL,'\n      <div topic=\"Phylactery of Faithfulness\" level=\"8\"><p><b>Phylactery of Faithfulness:</b> This item is a small box containing religious scripture affixed to a leather cord and tied around the forehead. There is no mundane way to determine what function this religious item performs until it is worn. The wearer of a <i>phylactery of faithfulness</i> is aware of any action or item that could adversely affect his alignment and his standing with his deity, including magical effects. He acquires this information prior to performing such an action or becoming associated with such an item if he takes a moment to contemplate the act.</p><p>Faint divination; CL 1st; Craft Wondrous Item, <i>detect chaos</i>,  <i>detect evil</i>,  <i>detect good</i>,  <i>detect law</i>; Price 1,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1489,'Phylactery of Undead Turning','Wondrous',NULL,'No','Moderate necromancy [good]','10','11,000 gp',NULL,'Craft Wondrous Item, 10th-level cleric',NULL,NULL,'\n      <div topic=\"Phylactery of Undead Turning\" level=\"8\"><p><b>Phylactery of Undead Turning:</b> This item is a boon to any character able to turn undead, allowing him to do so as if his class level were four levels higher than it actually is.</p><p>Moderate necromancy [good]; CL 10th; Craft Wondrous Item, 10th-level cleric; Price 11,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1490,'Pipes of Haunting','Wondrous',NULL,'No','Faint necromancy','4','6,000 gp',NULL,'Craft Wondrous Item, scare',NULL,'3 lb','\n      <div topic=\"Pipes of Haunting\" level=\"8\"><p><b>Pipes of Haunting:</b> This magic item appears to be a small set of pan pipes. When played by a person who succeeds on a DC 15 Perform (wind instruments) check, the pipes create an eerie, spellbinding tune. Those within 30 feet who hear the tune must succeed on a DC 13 Will save or become frightened for 4 rounds. Creatures with 6 or more Hit Dice are unaffected. <i>Pipes of haunting</i> can be sounded twice a day.</p><p>Faint necromancy; CL 4th; Craft Wondrous Item, <i>scare</i>; Price 6,000 gp; Weight 3 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1491,'Pipes of Pain','Wondrous',NULL,'No','Faint enchantment and evocation','6','12,000 gp',NULL,'Craft Wondrous Item, creator must have the bardic music class feature, sound burst',NULL,'3 lb','\n      <div topic=\"Pipes of Pain\" level=\"8\"><p><b>Pipes of Pain:</b> These appear to be like any other standard set of pipes with nothing to reveal their true nature. When played by someone who succeeds on a DC 15 Perform (wind instruments) check, the pipes create a wondrous melody. All within 30 feet must make a DC 14 Will save or be fascinated by the sound. (This is a mind-affecting sonic compulsion.)</p><p>As soon as the piping stops, all those affected are stricken by intense pain at even the slightest noise. Unless a character is in a totally silent area, she takes 1d4 points of damage per round for 2d4 rounds. During this time, damage from sonic attacks is doubled. Thereafter, the least noise causes an affected character to become shaken (except when she is in a totally silent area). This hypersensitivity is a curse and therefore hard to remove (see the <i>bestow curse</i> spell).</p><p>Faint enchantment and evocation; CL 6th; Craft Wondrous Item, creator must have the bardic music class feature, <i>sound burst</i>; Price 12,000 gp; Weight 3 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1492,'Pipes of the Sewers','Wondrous',NULL,'No','Faint conjuration','2','1,150 gp',NULL,'Craft Wondrous Item, charm animal, summon nature\'s ally I, wild empathy ability',NULL,'3 lb','\n      <div topic=\"Pipes of the Sewers\" level=\"8\"><p><b>Pipes of the Sewers:</b> These wooden pipes appear ordinary, but if the possessor learns the proper tune, he can attract 1d3 rat swarms if rats are within 400 feet. For each 50-foot distance the rats have to travel, there is a 1-round delay. The piper must continue playing until the rats appear, and when they do so, the piper must make a DC 10 Perform (wind instruments) check. Success means that they obey the piper\'s telepathic commands so long as he continues to play. Failure indicates that they turn on the piper. If for any reason the piper ceases playing, the rats leave immediately. If they are called again within a day, the Perform check DC is 15.</p><p>If the rats are under the control of another creature, add the HD of the controller to the Perform check DC. Once control is assumed, another check is required each round to maintain it if the other creature is actively seeking to reassert its control.</p><p>Faint conjuration; CL 2nd; Craft Wondrous Item, <i>charm animal</i>,  <i>summon nature\'s ally I</i>,  wild empathy ability; Price 1,150 gp; Weight 3 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1493,'Pipes of Sounding','Wondrous',NULL,'No','Faint illusion','2','1,800 gp',NULL,'Craft Wondrous Item, ghost sound',NULL,'3 lb','\n      <div topic=\"Pipes of Sounding\" level=\"8\"><p><b>Pipes of Sounding:</b> When played by a character who has the Perform (wind instruments) skill, these pipes create a variety of sounds. The figment sounds are the equivalent of <i>ghost sound</i> (caster level 2nd).</p><p>Faint illusion; CL 2nd; Craft Wondrous Item, <i>ghost sound</i>; Price 1,800 gp; Weight 3 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1494,'Portable Hole','Wondrous',NULL,'No','Moderate conjuration','12','20,000 gp',NULL,'Craft Wondrous Item, plane shift',NULL,NULL,'\n      <div topic=\"Portable Hole\" level=\"8\"><p><b>Portable Hole:</b> A portable hole is a circle of cloth spun from the webs of a phase spider interwoven with strands of ether and beams of starlight. When opened fully, a portable hole is 6 feet in diameter, but it can be folded up to be as small as a pocket handkerchief. When spread upon any surface, it causes an extradimensional space 10 feet deep to come into being. This hole can be picked up from inside or out by simply taking hold of the edges of the cloth and folding it up. Either way, the entrance disappears, but anything inside the hole remains.</p><p>The only air in the hole is that which enters when the hole is opened. It contains enough air to supply one Medium creature or two Small creatures for 10 minutes. The cloth does not accumulate weight even if its hole is filled. Each <i>portable hole</i> opens on its own particular nondimensional space. If a <i>bag of holding</i> is placed within a <i>Portable hole</i>, a rift to the Astral Plane is torn in that place. Both the bag and the cloth are sucked into the void and forever lost. If a <i>portable hole</i> is placed within a <i>bag of holding</i>,  it opens a gate to the Astral Plane. The hole, the bag, and any creatures within a 10-foot radius are drawn there, the <i>portable hole</i> and <i>bag of holding</i> being destroyed in the process.</p><p>Moderate conjuration; CL 12th; Craft Wondrous Item, <i>plane shift</i>; Price 20,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1495,'Restorative Ointment','Wondrous',NULL,'No','Faint conjuration','5','4,000 gp',NULL,'Craft Wondrous Item, cure light wounds, neutralize poison, remove disease',NULL,'1/2 lb','\n      <div topic=\"Restorative Ointment\" level=\"8\"><p><b>Restorative Ointment:</b> A jar of this unguent is 3 inches in diameter and 1 inch deep and contains five applications. Placed upon a poisoned wound or swallowed, the ointment detoxifies any poison (as <i>neutralize poison</i>). Applied to a diseased area, it removes disease (as <i>remove disease</i>). Rubbed on a wound, the ointment cures 1d8+5 points of damage (as <i>cure light wounds</i>).</p><p>Faint conjuration; CL 5th; Craft Wondrous Item, <i>cure light wounds</i>,  <i>neutralize poison</i>,  <i>remove disease</i>; Price 4,000 gp; Weight 1/2 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1496,'Ring Gates','Wondrous',NULL,'No','Strong conjuration','17','40,000 gp',NULL,'Craft Wondrous Item, gate',NULL,'1 lb. each','\n      <div topic=\"Ring Gates\" level=\"8\"><p><b>Ring Gates:</b> These always come in pairs-two iron rings, each about 18 inches in diameter. The rings must be on the same plane of existence and within 100 miles of each other to function. Whatever is put through one ring comes out the other, and up to 100 pounds of material can be transferred each day. (Objects only partially pushed through and then retracted do not count.) This useful device allows for instantaneous transport of items or messages, and even attacks. A character can reach through to grab things near the other ring, or even stab a weapon through if so desired. Alternatively, a character could stick his head through to look around. A spellcaster could even cast a spell through a <i>ring gate</i>. A Small character can make a DC 13 Escape Artist check to slip through. Creatures of Tiny, Diminutive, or Fine size can pass through easily. Each ring has a \'entry side\' and an \'exit side,\' both marked with appropriate symbols.</p><p>Strong conjuration; CL 17th; Craft Wondrous Item, <i>gate</i>; Price 40,000 gp; Weight 1 lb. each.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1497,'Robe of the Archmagi','Wondrous',NULL,'No','Strong varied','14','75,000 gp',NULL,'Craft Wondrous Item, antimagic field, mage armor or shield of faith, creator must be of same alignment as robe',NULL,'1 lb','\n      <div topic=\"Robe of the Archmagi\" level=\"8\"><p><b>Robe of the Archmagi:</b> This normal-appearing garment can be white (01-45 on d%, good alignment), gray (46-75, neither good nor evil alignment), or black (76-100, evil alignment). Its wearer, if an arcane spellcaster, gains the following powers.</p><ul>\n <li> +5 armor bonus to AC.</li>\n <li> Spell resistance 18.</li>\n <li> +4 resistance bonus on all saving throws.</li>\n <li> +2 enhancement bonus on caster level checks made to overcome spell resistance.</li>\n</ul><p>If a white robe is donned by an evil character, she immediately gains three negative levels. The reverse is true with respect to a black robe donned by a good character. An evil or good character who puts on a gray robe, or a neutral character who dons either a white or black robe, gains two negative levels. While these negative levels never result in lost levels, they remain as long as the garment is worn and cannot be overcome in any way (including <i>restoration</i> spells).</p><p>Strong varied; CL 14th; Craft Wondrous Item, <i>antimagic field</i>,  <i>mage armor</i> or <i>shield of faith</i>,  creator must be of same alignment as robe; Price 75,000 gp; Weight 1 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
